WITH filtered AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, CAST(is_flagged AS INT) AS is_flagged_flag FROM transactions WHERE account_id IN (2, 21, 36)) SELECT CASE WHEN amount >= 4200 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, DATE_TRUNC('YEAR', txn_time) AS year_start, SUM(CASE WHEN merchant = 'Amazon' THEN amount ELSE 0 END) AS amazon_amount, SIZE(COLLECT_SET(txn_type)) AS num_txn_types, COUNT(*) FILTER (WHERE merchant = 'Starbucks') AS starbucks_rows, MIN(txn_time) AS first_txn_time, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS duration_min, ROUND(SUM(is_flagged_flag) / NULLIF(COUNT(CASE WHEN txn_type = 'DEBIT' THEN 1 END), 0), 2) AS is_flagged_flag_per_debit FROM filtered GROUP BY amount_tier, year_start
